#include <bits/stdc++.h>using namespace std;using ll = long long; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;    while (t--) {        ll n;        cin >> n;        vector<ll> a(n), b(n);        for (ll i = 0; i < n; i++) cin >> a[i];        for (ll i = 0; i < n; i++) cin >> b[i];         vector<ll> pref(n + 1, 0);        for (ll i = 0; i < n; i++) pref[i + 1] = pref[i] + b[i];         sort(a.begin(), a.end());         ll maxScore = 0;        for (ll i = 0; i < n; i++) {            ll x = a[i];            ll swords = n - i;            ll l = 0, r = n;            while (l < r) {                ll m = (l + r + 1) / 2;                if (pref[m] <= swords) l = m;                else r = m - 1;            }            ll score = x * l;            maxScore = max(maxScore, score);        }         cout << maxScore << "\n";    }    return 0;}